 * Parse one variable specification of an expression.
 *
 * @param {string} spec text between commas
 * @param {number} start index of the `{` that opens the expression
 * @returns {{ name: string, explode: boolean, maxLength: number | null }} the parsed specification
 */
function parseVarSpec(spec, start) {
  if (spec === '') throw new UriTemplateError(`empty variable specification at ${start}`, start);
  let name = spec;
  let explode = false;
  let maxLength = null;
  let modifier = null;
  if (name.endsWith('*')) {
    explode = true;
    name = name.slice(0, -1);
  } else {
    const colon = name.indexOf(':');
    if (colon !== -1) {
      modifier = name.slice(colon + 1);
      name = name.slice(0, colon);
    }
  }
  if (!NAME_RE.test(name)) throw new UriTemplateError(`invalid variable name '${name}' at ${start}`, start);
  if (modifier !== null) {
    if (!/^[1-9][0-9]{0,3}$/.test(modifier)) {
      throw new UriTemplateError(`invalid prefix modifier ':${modifier}' at ${start}`, start);
    }
    maxLength = Number(modifier);
  }
  return { name, explode, maxLength };
}

