 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');
  const parts = [];
  let literal = '';
  let i = 0;
  const flush = () => {
    if (literal !== '') {
      parts.push({ type: 'literal', value: literal });
      literal = '';
    }
  };
  while (i < template.length) {
    const char = template[i];
    if (char === '}') throw new UriTemplateError(`unexpected '}' at ${i}`, i);
    if (char !== '{') {
      literal += char;
      i += 1;
      continue;
    }
    const start = i;
    const end = template.indexOf('}', start + 1);
    if (end === -1) throw new UriTemplateError(`unterminated expression at ${start}`, start);
    const body = template.slice(start + 1, end);
    if (body === '') throw new UriTemplateError(`empty expression at ${start}`, start);
    let operator = '';
    let rest = body;
    if (RESERVED_OPERATORS.includes(body[0])) {
      throw new UriTemplateError(`reserved operator '${body[0]}' at ${start}`, start);
    }
    if (OPERATORS.includes(body[0])) {
      operator = body[0];
      rest = body.slice(1);
    }
    if (rest === '') throw new UriTemplateError(`empty variable specification at ${start}`, start);
    const variables = rest.split(',').map((spec) => parseVarSpec(spec, start));
    flush();
    parts.push({ type: 'expression', operator, variables });
    i = end + 1;
  }
  flush();
  return parts;
}
