import { UriTemplateError, parse } from './parse.js';

const RULES = {
  '': { first: '', sep: ',', named: false, ifEmpty: '', reserved: false },
  '+': { first: '', sep: ',', named: false, ifEmpty: '', reserved: true },
  '#': { first: '#', sep: ',', named: false, ifEmpty: '', reserved: true },
  '.': { first: '.', sep: '.', named: false, ifEmpty: '', reserved: false },
  '/': { first: '/', sep: '/', named: false, ifEmpty: '', reserved: false },
  ';': { first: ';', sep: ';', named: true, ifEmpty: '', reserved: false },
  '?': { first: '?', sep: '&', named: true, ifEmpty: '=', reserved: false },
  '&': { first: '&', sep: '&', named: true, ifEmpty: '=', reserved: false },
};

const UNRESERVED = /^[A-Za-z0-9\-._~]$/;
const RESERVED = ":/?#[]@!$&'()*+,;=";
const encoder = new TextEncoder();

/**
 * Percent-encode one character as uppercase UTF-8 triplets.
 *
 * @param {string} char a single code point
 * @returns {string} the triplets
 */
function pctEncode(char) {
  return Array.from(encoder.encode(char))
    .map((byte) => `%${byte.toString(16).toUpperCase().padStart(2, '0')}`)
    .join('');
}

/**
 * Encode text keeping unreserved characters only.
 *
 * @param {string} text input
 * @returns {string} encoded text
 */
function encodeUnreserved(text) {
  let out = '';
  for (const char of text) out += UNRESERVED.test(char) ? char : pctEncode(char);
  return out;
}

/**
 * Encode text keeping unreserved and reserved characters and existing triplets.
 *
 * @param {string} text input
 * @returns {string} encoded text
 */
function encodeReserved(text) {
  let out = '';
  let i = 0;
  while (i < text.length) {
    if (text[i] === '%' && /^[0-9A-Fa-f]{2}$/.test(text.slice(i + 1, i + 3))) {
      out += text.slice(i, i + 3);
      i += 3;
      continue;
    }
    const char = String.fromCodePoint(text.codePointAt(i));
    out += UNRESERVED.test(char) || RESERVED.includes(char) ? char : pctEncode(char);
    i += char.length;
  }
  return out;
}

/**
 * Convert a scalar value to its text form.
 *
 * @param {unknown} value candidate value
 * @param {string} name variable name, for errors
 * @returns {string} the text
 */
function scalarText(value, name) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  if (typeof value === 'boolean') return String(value);
  throw new UriTemplateError(`value for '${name}' is not a string, number or boolean`);
}

/**
 * Expand a single variable into its pieces.
 *
 * @param {{ name: string, explode: boolean, maxLength: number | null }} spec variable specification
 * @param {unknown} value the bound value
 * @param {{ named: boolean, ifEmpty: string, reserved: boolean }} rules operator rules
 * @returns {string[]} the pieces contributed
 */
function expandVariable(spec, value, rules) {
  const { name, explode, maxLength } = spec;
  const encode = rules.reserved ? encodeReserved : encodeUnreserved;
  const pair = (key, encoded) => (rules.named && encoded === '' ? key + rules.ifEmpty : `${key}=${encoded}`);

  if (Array.isArray(value)) {
    const items = value.filter((item) => item !== null && item !== undefined);
    if (items.length === 0) return [];
    if (maxLength !== null) {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);
    }
    const encoded = items.map((item) => encode(scalarText(item, name)));
    if (explode) return encoded.map((item) => (rules.named ? pair(name, item) : item));
    const joined = encoded.join(',');
    return [rules.named ? `${name}=${joined}` : joined];
  }

  if (typeof value === 'object') {
    const entries = Object.entries(value).filter(([, item]) => item !== null && item !== undefined);
    if (entries.length === 0) return [];
    if (maxLength !== null) {
      throw new UriTemplateError(`prefix modifier applied to a composite value: '${name}'`);
    }
    const encoded = entries.map(([key, item]) => [encode(key), encode(scalarText(item, name))]);
    if (explode) return encoded.map(([key, item]) => pair(key, item));
    const joined = encoded.flat().join(',');
    return [rules.named ? `${name}=${joined}` : joined];
  }

  let text = scalarText(value, name);
  if (maxLength !== null) text = Array.from(text).slice(0, maxLength).join('');
  const encoded = encode(text);
  return [rules.named ? pair(name, encoded) : encoded];
}

/**
 * Expand a template against a set of variables.
 *
 * @param {string} template template text
 * @param {Record<string, unknown>} variables values bound by name, read as own properties
 * @returns {string} the expanded URI
 */
export function expand(template, variables) {
  const parts = parse(template);
  if (typeof variables !== 'object' || variables === null) {
    throw new UriTemplateError('variables must be an object');
  }
  let out = '';
  for (const part of parts) {
    if (part.type === 'literal') {
      out += encodeReserved(part.value);
      continue;
    }
    const rules = RULES[part.operator];
    const pieces = [];
    for (const spec of part.variables) {
      if (!Object.prototype.hasOwnProperty.call(variables, spec.name)) continue;
      const value = variables[spec.name];
      if (value === null || value === undefined) continue;
      pieces.push(...expandVariable(spec, value, rules));
    }
    if (pieces.length > 0) out += rules.first + pieces.join(rules.sep);
  }
  return out;
}
"}

