const NAME_RE = new RegExp(`^${NAME_CHAR}+(?:\\.${NAME_CHAR}+)*$`);

/**
 * Parse one variable specification of an expression.
 *
 * @param {string} spec text between commas
 * @param {number} start index of the `{` that opens the expression
 * @returns {{ name: string, explode: boolean, maxLength: number | null }} the parsed specification
 */
function parseVarSpec(spec, start) {
  if (spec === '') throw new UriTemplateError(`empty variable specification at ${start}`, start);
  let name = spec;
  let explode = false;
  let modifier = null;
  if (name.endsWith('*')) {
    explode = true;
    name = name.slice(0, -1);
  } else {
    const colon = name.indexOf(':');
    if (colon !== -1) {
      modifier = name.slice(colon + 1);
      name = name.slice(0, colon);
    }
  }
  if (!NAME_RE.test(name)) throw new UriTemplateError(`invalid variable name '${name}' at ${start}`, start);
  let maxLength = null;
  if (modifier !== null) {
    if (!/^[1-9][0-9]{0,3}$/.test(modifier)) {
      throw new UriTemplateError(`invalid prefix modifier ':${modifier}' at ${start}`, start);
    }
    maxLength = Number(modifier);
  }
  return { name, explode, maxLength };
}

/**
 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');
  const parts = [];
  let literal = '';
  let i = 0;
  const flush = () => {
    if (literal !== '') {
      parts.push({ type: 'literal', value: literal });
      literal = '';
    }
  };
  while (i < template.length) {
    const char = template[i];
    if (char === '}') throw new UriTemplateError(`unexpected '}' at ${i}`, i);
    if (char !== '{') {
      literal += char;
      i += 1;
      continue;
    }
    const start = i;
    const end = template.indexOf('}', start + 1);
